css:
.checkbox-container {
  --checkbox-size: 32px;
  --border-radius: 50%;
  --primary-color: #ffc008;
  --checkmark-color: #593f28;

  display: block;
  position: relative;
  cursor: pointer;
  user-select: none;
  border-radius: var(--border-radius);
}

/* Hide the default checkbox */
.checkbox-container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

/* Create a custom checkbox */
.checkbox-container .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: var(--checkbox-size);
  width: var(--checkbox-size);
  background-color: #e9eaeb;
  border-radius: inherit;
  border: 1px solid #d5d7da;
}

.checkbox-container .checkmark:before {
  content: "";
  position: absolute;
  inset: 15%;
  background: white;
  border-radius: inherit;
  box-shadow:
    0px 1px 1.1px rgba(0, 0, 0, 0.12),
    0px 10px 10px rgba(0, 0, 0, 0.12);
  z-index: 1;
  transition: scale 0.2s ease-in-out;
}

.checkbox-container .checkmark svg {
  scale: 0;
  fill: var(--checkmark-color);
  rotate: -30deg;
  position: relative;
  width: 80%;
  height: auto;
  z-index: 2;
  left: 25%;
  justify-content: center;
  transform-origin: 25% 75%;
  transition: all 0.2s cubic-bezier(0.785, 0.135, 0.15, 0.86);
}

.checkbox-container:hover .checkmark:before {
  scale: 1.1;
}

.checkbox-container:active .checkmark:before {
  scale: 0.9;
}

/* When the checkbox is checked.... */
.checkbox-container input:checked ~ .checkmark {
  background-color: var(--primary-color);
}

.checkbox-container input:checked ~ .checkmark svg {
  scale: 1;
  rotate: 0deg;
}
